"""Render generated artifacts for one variant as ``{relative path: text}``."""

from __future__ import annotations

import csv
import io
import json
import uuid
from typing import Any

import yaml
from pydantic import BaseModel

from plantgen.allocate import (
    MASTER_FC,
    OTSIM_BASE,
    READ_FC,
    Allocation,
    IecAddress,
    TagAddress,
    access,
    rio_devices,
)
from plantgen.model import ModbusEndpoint, Plant, Tag, is_analog, is_writable

GENERATOR: str = "plantgen"
HEADER: str = (
    "Generated by plantgen from plant/plant.yaml (variant {variant}). Do not edit."
)
#: Namespace for deterministic FUXA tag IDs (uuid5 of the tag name).
FUXA_NAMESPACE: uuid.UUID = uuid.uuid5(
    uuid.NAMESPACE_DNS, "fuxa.cherrymountain.example"
)
#: FUXA alarm severities for ISA-18.2 priorities.
FUXA_SEVERITY: dict[str, str] = {
    "critical": "highhigh",
    "high": "high",
    "medium": "low",
    "low": "info",
}


def render_all(plant: Plant, alloc: Allocation) -> dict[str, str]:
    """Every output file for the variant."""
    out = {
        "tags.json": _json(tags_doc(plant, alloc)),
        "registers.json": _json(registers_doc(plant, alloc)),
        "registers.csv": registers_csv(plant, alloc),
        "alarms.json": _json(alarms_doc(plant, alloc)),
        "helics.json": _json(helics_doc(plant)),
        "phenix/ot-sim.yaml": _yaml(plant, otsim_app(plant)),
        "phenix/ntp.yaml": _yaml(plant, ntp_app(plant)),
    }
    for plc, rios in alloc.plc_rios.items():
        out[f"openplc/{plc}/modbus_master.json"] = _json(
            modbus_master(plant, alloc, plc, rios)
        )
        out[f"openplc/{plc}/mbconfig.cfg"] = mbconfig(plant, alloc, plc, rios)
        out[f"openplc/{plc}/located_vars.st"] = located_vars(plant, alloc, plc)
    for scada in plant.hosts_by_role("scada"):
        out[f"fuxa/{scada.name}-tags.json"] = _json(fuxa_doc(plant, alloc))
    return out


def _json(doc: Any) -> str:
    return json.dumps(doc, indent=2, ensure_ascii=False) + "\n"


def _yaml(plant: Plant, doc: Any) -> str:
    body = yaml.safe_dump(doc, sort_keys=False, default_flow_style=False, width=1000)
    return f"# {HEADER.format(variant=plant.variant)}\n" + body


def fuxa_id(name: str) -> str:
    """Deterministic FUXA tag ID derived from the tag name."""
    return f"t_{uuid.uuid5(FUXA_NAMESPACE, name)}"


# ---------------------------------------------------------------------------
# Tag database and register maps
# ---------------------------------------------------------------------------


def _tag_base(t: Tag) -> dict[str, Any]:
    d: dict[str, Any] = {"name": t.name, "desc": t.desc, "type": t.type}
    if t.units:
        d["units"] = t.units
    if t.range:
        d["range"] = list(t.range)
    if is_analog(t.type):
        d["scaling"] = t.scaling
    return d


def tags_doc(plant: Plant, alloc: Allocation) -> dict[str, Any]:
    """Expanded tag database, including generated alarm bits."""
    tags = []
    for t in plant.tags:
        d = _tag_base(t)
        d.update({"area": t.area, "unit": t.unit, "source": t.source, "plc": t.plc})
        if t.device:
            d.update(
                {
                    "rio": t.rio,
                    "federate": t.federate,
                    "device": t.device.name,
                    "device_type": t.device.type,
                    "point": t.point,
                    "helics_key": t.helics_key,
                }
            )
        if t.generated:
            d["generated"] = True
        if t.alarms:
            d["alarms"] = [a.name for a in t.alarms]
        tags.append(d)
    return {"generator": GENERATOR, "variant": plant.variant, "tags": tags}


class RegisterRow(BaseModel):
    """One tag in every addressing convention (DESIGN.md §12.5)."""

    tag: str
    type: str
    units: str | None
    scaling: int | None
    rio: str | None
    rio_space: str | None
    otsim_register: int | None  # ot-sim literal register number = PDU address
    master_fc: int | None  # OpenPLC modbus_master function code
    master_offset: int | None  # OpenPLC modbus_master PDU offset
    plc: str
    plc_iec: str
    slave_space: str
    slave_read_fc: int
    slave_pdu_address: int  # OpenPLC modbus_slave, 0-based
    fuxa_memaddress: str
    fuxa_address: int  # FUXA, 1-based
    scada_access: str

    @classmethod
    def of(cls, a: TagAddress) -> RegisterRow:
        """Build the row for one allocated tag."""
        t = a.tag
        return cls(
            tag=t.name,
            type=t.type,
            units=t.units,
            scaling=t.scaling if is_analog(t.type) else None,
            rio=t.rio,
            rio_space=a.rio_space,
            otsim_register=a.rio_address,
            master_fc=a.master_fc,
            master_offset=a.rio_address,
            plc=t.plc,
            plc_iec=str(a.plc_iec),
            slave_space=a.slave_space,
            slave_read_fc=READ_FC[a.slave_space],
            slave_pdu_address=a.slave_address,
            fuxa_memaddress=a.fuxa_memaddress,
            fuxa_address=a.fuxa_address,
            scada_access=access(t),
        )


def register_rows(plant: Plant, alloc: Allocation) -> list[RegisterRow]:
    """Register rows in tag order."""
    return [RegisterRow.of(alloc.tags[t.name]) for t in plant.tags]


def registers_doc(plant: Plant, alloc: Allocation) -> dict[str, Any]:
    """Register map in all addressing conventions, one row per tag."""
    rows = [r.model_dump() for r in register_rows(plant, alloc)]
    return {
        "generator": GENERATOR,
        "variant": plant.variant,
        "conventions": {
            "otsim_register": "ot-sim literal register number; equals the PDU address "
            "(coil 1.., discrete 10001.., input 30001.., holding 40001..)",
            "master_offset": "OpenPLC modbus_master PDU offset (= otsim_register)",
            "plc_iec": "IEC 61131-3 located variable in the PLC",
            "slave_pdu_address": "OpenPLC modbus_slave PDU address (0-based); "
            "holding >= 1024 is %MW",
            "fuxa_address": "FUXA 1-based address (FUXA subtracts 1) within memaddress",
        },
        "registers": rows,
    }


def registers_csv(plant: Plant, alloc: Allocation) -> str:
    """CSV view of :func:`registers_doc`."""
    rows = [
        {k: "" if v is None else v for k, v in r.model_dump().items()}
        for r in register_rows(plant, alloc)
    ]
    buf = io.StringIO()
    writer = csv.DictWriter(
        buf, fieldnames=list(RegisterRow.model_fields), lineterminator="\n"
    )
    writer.writeheader()
    writer.writerows(rows)
    return buf.getvalue()


# ---------------------------------------------------------------------------
# Alarms and HELICS
# ---------------------------------------------------------------------------


def alarms_doc(plant: Plant, alloc: Allocation) -> dict[str, Any]:
    """Rationalized alarms for the PLC program and FUXA alarm definitions."""
    alarms = []
    for a in plant.alarms:
        bit = alloc.tags[a.name]
        src = plant.tag(a.source)
        alarms.append(
            {
                "name": a.name,
                "source": a.source,
                "kind": a.kind,
                "limit": a.limit,
                "units": src.units,
                "setpoint": a.setpoint,
                "delay_s": a.delay_s,
                "priority": a.priority,
                "fuxa_severity": FUXA_SEVERITY[a.priority],
                "cause": a.cause,
                "consequence": a.consequence,
                "action": a.action,
                "response_time_s": a.response_time_s,
                "plc": src.plc,
                "plc_iec": str(bit.plc_iec),
                "fuxa_tag_id": fuxa_id(a.name),
                "text": f"{src.desc}: {a.kind} alarm",
            }
        )
    return {"generator": GENERATOR, "variant": plant.variant, "alarms": alarms}


def _helics_type(tag_type: str) -> str:
    return "double" if is_analog(tag_type) else "boolean"


def helics_doc(plant: Plant) -> dict[str, Any]:
    """Explicit HELICS publication, subscription, and endpoint lists."""
    feds = plant.spec.federates
    broker = plant.spec.helics.broker
    broker_host = plant.hosts[broker.hostname]
    doc: dict[str, Any] = {
        "generator": GENERATOR,
        "variant": plant.variant,
        "broker": {
            "host": broker.hostname,
            "interface": broker.interface,
            "address": broker_host.ip(broker.interface),
            "core_type": "zmq",
        },
        "end_time_s": plant.spec.helics.end_time_s,
        "federates": {},
        "io_federates": {},
    }
    for fname, fed in plant.federates.items():
        pubs = []
        writes = []
        for dev in plant.devices:
            if dev.federate != fname:
                continue
            for point in plant.device_types[dev.type].values():
                tag = _bound_tag(plant, dev.name, point.name)
                pubs.append(
                    {
                        "key": f"{dev.topic}.{point.name}",
                        "type": _helics_type(point.type),
                        "units": tag.units if tag else None,
                        "tag": tag.name if tag else None,
                        "unit": dev.unit,
                        "device": dev.name,
                        "device_type": dev.type,
                        "zone": dev.zone,
                        "point": point.name,
                    }
                )
                if is_writable(point.type):
                    writes.append(f"{dev.name}.{point.name}")
        for out in fed.outputs:
            pubs.append(
                {
                    "key": f"{fname}/{out.key}",
                    "type": out.type,
                    "units": out.units,
                    "output": out.key,
                }
            )
        subs = []
        defaults = {}
        for inp in fed.inputs:
            source = inp.key.split("/")[0]
            if source in feds:
                subs.append({"key": inp.key, "type": inp.type, "units": inp.units})
            else:
                defaults[inp.key] = inp.default
        sim = plant.spec.sim
        doc["federates"][fname] = {
            "host": fed.host,
            "period_s": fed.period_s,
            "endpoint": f"{fname}/{fed.endpoint}",
            "accepted_updates": writes,
            "publications": pubs,
            "subscriptions": subs,
            "input_defaults": defaults,
            "ambient_psia": plant.file.site.ambient_psia,
            "sim": {
                "compression": sim.compression,
                "noise": sim.noise,
                "seed": sim.seed,
                "initial_state": {
                    unit: st.model_dump(exclude_none=True)
                    for unit, st in sim.initial_state.items()
                },
            },
        }
    for rio in plant.hosts_by_role("rio"):
        devs = rio_devices(plant, rio.name)
        subs = []
        sends = []
        for dev in devs:
            for point in plant.device_types[dev.type].values():
                subs.append(f"{dev.topic}.{point.name}")
                if is_writable(point.type):
                    sends.append(
                        {
                            "tag": f"{dev.name}.{point.name}",
                            "endpoint": doc["federates"][dev.federate]["endpoint"],
                        }
                    )
        doc["io_federates"][rio.name] = {
            "federate_name": rio.name,
            "subscriptions": subs,
            "endpoint": f"{rio.name}/updates" if sends else None,
            "sends": sends,
        }
    doc["federate_count"] = len(doc["federates"]) + len(doc["io_federates"])
    return doc


def _bound_tag(plant: Plant, device: str, point: str) -> Tag | None:
    for t in plant.tags:
        if t.device and t.device.name == device and t.point == point:
            return t
    return None


# ---------------------------------------------------------------------------
# phenix app blocks
# ---------------------------------------------------------------------------


def otsim_app(plant: Plant) -> dict[str, Any]:
    """Scenario ``ot-sim`` app block (DESIGN.md §15.2 shape)."""
    used = []
    for d in plant.devices:
        if d.type not in used:
            used.append(d.type)
    infra: dict[str, Any] = {}
    for dtype in used:
        points = {}
        for p in plant.device_types[dtype].values():
            entry: dict[str, Any] = {"type": p.type}
            if is_analog(p.type):
                # One register per point: phenix-apps defaults analog points
                # to int32 (two registers), which breaks the register map.
                modbus: dict[str, Any] = {"data-type": "uint16"}
                if p.scaling is not None:
                    modbus["scaling"] = p.scaling
                entry["modbus"] = modbus
            points[p.name] = entry
        infra[dtype] = points
    helics = plant.spec.helics
    broker = helics.broker
    feds = list(plant.federates)
    md: dict[str, Any] = {
        "infrastructure": "brewery",
        "infrastructures": {"brewery": infra},
        "helics": {
            "broker": {"hostname": f"{broker.hostname}|{broker.interface}"},
            "federate": feds[0] if feds else "cellar",
            "endpoint": "updates",
            "end-time": helics.end_time_s,
        },
        "cpu-module": {"api-endpoint": "127.0.0.1:9101"},
    }
    if plant.spec.ground_truth:
        md["ground-truth-module"] = {
            "elastic": {
                "endpoint": f"http://{plant.hosts['sim-ctl'].ip('mgmt')}:9200",
                "index-base-name": "cherrymountain-truth",
            }
        }
    hosts = []
    for rio in plant.hosts_by_role("rio"):
        mb = rio.modbus or ModbusEndpoint()
        hosts.append(
            {
                "hostname": rio.name,
                "metadata": {
                    "type": "fd-server",
                    "modbus": {
                        "interface": f"{mb.interface}:{mb.port}",
                        "devices": [
                            {"name": d.topic, "type": d.type}
                            for d in rio_devices(plant, rio.name)
                        ],
                    },
                },
            }
        )
    return {"name": "ot-sim", "metadata": md, "hosts": hosts}


def ntp_app(plant: Plant) -> dict[str, Any]:
    """Scenario ``ntp`` app block in app mode, every host listed."""
    ntp = plant.spec.ntp
    hosts = []
    for name in plant.spec.hosts:
        md = ntp.hosts[name].model_dump(exclude_none=True)
        hosts.append({"hostname": name, "metadata": md})
    return {
        "name": "ntp",
        "metadata": {"defaultSource": ntp.default_source.model_dump()},
        "hosts": hosts,
    }


# ---------------------------------------------------------------------------
# OpenPLC
# ---------------------------------------------------------------------------


def _rio_blocks(alloc: Allocation, rio: str) -> dict[str, tuple[int, int]]:
    """Per space: (first ot-sim register, count)."""
    blocks: dict[str, tuple[int, int]] = {}
    for space in OTSIM_BASE:
        addrs = [r.address for r in alloc.rio_registers[rio] if r.space == space]
        if addrs:
            blocks[space] = (min(addrs), len(addrs))
    return blocks


def _iec_start(alloc: Allocation, rio: str, space: str) -> IecAddress:
    regs = [r for r in alloc.rio_registers[rio] if r.space == space and r.tag]
    first = min(regs, key=lambda r: r.address)
    return alloc.tags[first.tag.name].plc_iec  # type: ignore[union-attr]


def modbus_master(
    plant: Plant, alloc: Allocation, plc: str, rios: list[str]
) -> list[dict[str, Any]]:
    """OpenPLC v4 ``modbus_master`` plugin config (runtime JSON schema)."""
    poll = plant.hosts[plc].poll_ms
    devices = []
    for rio in rios:
        host = plant.hosts[rio]
        mb = host.modbus or ModbusEndpoint()
        points = []
        for space in ("discrete", "input", "coil", "holding"):
            block = _rio_blocks(alloc, rio).get(space)
            if not block:
                continue
            start, count = block
            points.append(
                {
                    "fc": MASTER_FC[space],
                    "offset": str(start),
                    "iec_location": str(_iec_start(alloc, rio, space)),
                    "len": count,
                    "cycle_time_ms": poll,
                    "error_handling": "keep-last-value",
                }
            )
        devices.append(
            {
                "name": rio,
                "protocol": "MODBUS",
                "config": {
                    "type": "SLAVE",
                    "transport": "tcp",
                    "host": host.ip(mb.interface),
                    "port": mb.port,
                    "slave_id": mb.unit_id,
                    "timeout_ms": 1000,
                    "io_points": points,
                },
            }
        )
    return devices


def mbconfig(plant: Plant, alloc: Allocation, plc: str, rios: list[str]) -> str:
    """OpenPLC v3 ``mbconfig.cfg`` (fallback; same IEC map as v4)."""
    poll = plant.hosts[plc].poll_ms
    lines = [
        f"# {HEADER.format(variant=plant.variant)}",
        "# OpenPLC v3 fallback: slave devices map to %IX100.0, %QX100.0, %IW100,",
        "# and %QW100, the same IEC locations as the v4 modbus_master config.",
        f'Num_Devices = "{len(rios)}"',
        f'Polling_Period = "{poll}"',
        'Timeout = "1000"',
    ]
    for i, rio in enumerate(rios):
        host = plant.hosts[rio]
        mb = host.modbus or ModbusEndpoint()
        blocks = _rio_blocks(alloc, rio)
        di, co, ir, hr = (
            blocks.get(space, (0, 0))
            for space in ("discrete", "coil", "input", "holding")
        )
        p = f"device{i}"
        lines += [
            f'{p}.name = "{rio}"',
            f'{p}.slave_id = "{mb.unit_id}"',
            f'{p}.protocol = "TCP"',
            f'{p}.address = "{host.ip(mb.interface)}"',
            f'{p}.IP_Port = "{mb.port}"',
            f'{p}.RTU_Baud_Rate = "115200"',
            f'{p}.RTU_Parity = "None"',
            f'{p}.RTU_Data_Bits = "8"',
            f'{p}.RTU_Stop_Bits = "1"',
            f'{p}.RTU_TX_Pause = "0"',
            f'{p}.Discrete_Inputs_Start = "{di[0]}"',
            f'{p}.Discrete_Inputs_Size = "{di[1]}"',
            f'{p}.Coils_Start = "{co[0]}"',
            f'{p}.Coils_Size = "{co[1]}"',
            f'{p}.Input_Registers_Start = "{ir[0]}"',
            f'{p}.Input_Registers_Size = "{ir[1]}"',
            f'{p}.Holding_Registers_Read_Start = "0"',
            f'{p}.Holding_Registers_Read_Size = "0"',
            f'{p}.Holding_Registers_Start = "{hr[0]}"',
            f'{p}.Holding_Registers_Size = "{hr[1]}"',
        ]
    return "\n".join(lines) + "\n"


def st_name(tag_name: str) -> str:
    """IEC identifier for a tag: dots become underscores."""
    return tag_name.replace(".", "_")


def located_vars(plant: Plant, alloc: Allocation, plc: str) -> str:
    """Structured Text located-variable declarations for the PLC program."""
    lines = [
        f"(* {HEADER.format(variant=plant.variant)} *)",
        "(* Analog values are raw registers: engineering value = raw / 10^scaling. *)",
        "(* RIO I/O is at %IX100.0 / %QX100.0 / %IW100 / %QW100 (v3 and v4 alike). *)",
        "(* PLC memory: bits from %QX0.0 (coils), words from %MW0 (holding 1024+). *)",
        "VAR",
    ]
    for t in plant.tags:
        if t.plc != plc:
            continue
        a = alloc.tags[t.name]
        iec_type = "UINT" if is_analog(t.type) else "BOOL"
        note = t.desc
        if is_analog(t.type):
            note += f", {t.units}, x{10**t.scaling}"
        lines.append(f"  {st_name(t.name)} AT {a.plc_iec} : {iec_type}; (* {note} *)")
    lines.append("END_VAR")
    return "\n".join(lines) + "\n"


# ---------------------------------------------------------------------------
# FUXA
# ---------------------------------------------------------------------------


def fuxa_doc(plant: Plant, alloc: Allocation) -> dict[str, Any]:
    """FUXA Modbus TCP device and tag list for each PLC with tags."""
    devices = []
    for plc in alloc.plc_rios:
        host = plant.hosts[plc]
        mb = host.modbus or ModbusEndpoint()
        tags = []
        for t in plant.tags:
            if t.plc != plc:
                continue
            a = alloc.tags[t.name]
            entry: dict[str, Any] = {
                "id": fuxa_id(t.name),
                "name": t.name,
                "label": t.desc,
                "type": "UInt16" if is_analog(t.type) else "Bool",
                "memaddress": a.fuxa_memaddress,
                "address": a.fuxa_address,
                "access": access(t),
            }
            if is_analog(t.type):
                entry["divisor"] = 10**t.scaling
                entry["units"] = t.units
                entry["range"] = list(t.range) if t.range else None
            tags.append(entry)
        devices.append(
            {
                "name": plc,
                "type": "ModbusTCP",
                "property": {
                    "address": host.ip(mb.interface),
                    "port": mb.port,
                    "slaveid": mb.unit_id,
                },
                "polling": 1000,
                "tags": tags,
            }
        )
    return {
        "generator": GENERATOR,
        "variant": plant.variant,
        "notes": "address is 1-based (FUXA subtracts 1); value = raw / divisor",
        "devices": devices,
    }
